INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('radical-race', 'Radical Race', 'Radical Race', 'radical race krix huoxing jingsu xuanfu motuo phoboslab dominic szablewski andreas loesch', 'Dominic Szablewski (Phoboslab)', '', '', NULL, '', 0, 2013, 'action', '["竞速","动作"]', 10, 0.12, 'io', 'https://phoboslab.org/krace/', 0, 0, 0, 1, 0, 0, 1, 'short', 'hosted', '在火星上骑着悬浮摩托，一路往前逃', '一款无尽横向竞速：按 X 开始，在火星地表的峡谷里尽量开得更远。', 'An endless side-scrolling racer: press X to start, and see how far you can ride across the canyons of Mars.', '由 Dominic Szablewski（Phoboslab）编程，Andreas Lösch 负责画面与音乐，2013 年起在 phoboslab.org/krace 公开发布。原页托管在 phoboslab.org/krace，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Programmed by Dominic Szablewski (Phoboslab), with graphics and music by Andreas Lösch, and published on phoboslab.org/krace since 2013. Hosted at phoboslab.org/krace; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/radical-race.jpg', 1280, 800, 'center', '["assets/posters/radical-race.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -48, 1795399200000, 'Ride a hover bike across Mars and see how far you can go.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('plan-9', 'Plan 9 From Planet Kr1x', 'Plan 9 From Planet Kr1x', 'plan 9 from planet kr1x jiuhao xingqiu sheji jieji phoboslab dominic szablewski andreas loesch tim juraschka', 'Dominic Szablewski (Phoboslab)', '', '', NULL, '', 0, 2012, 'action', '["射击","动作","街机"]', 280, 0.1, 'io', 'https://phoboslab.org/kr1x/', 0, 0, 0, 1, 0, 0, 1, 'short', 'hosted', '在星空里开火，把来袭的东西打掉', '一款街机射击：按 Enter 开始，在深空里躲开陨石与敌机并还击。', 'An arcade shooter: press Enter to start, dodge asteroids and enemy craft in deep space, and fire back.', '由 Dominic Szablewski（Phoboslab）编程，Andreas Lösch 负责画面与音乐，Tim Juraschka 负责音效，2012 年起在 phoboslab.org/kr1x 公开发布。是作者和两位朋友给共同朋友做的生日作品。原页托管在 phoboslab.org/kr1x，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Programmed by Dominic Szablewski (Phoboslab), with graphics and music by Andreas Lösch and sound effects by Tim Juraschka, and published on phoboslab.org/kr1x since 2012. Made with two friends as a birthday gift. Hosted at phoboslab.org/kr1x; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/plan-9.jpg', 1280, 800, 'center', '["assets/posters/plan-9.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -47, 1795399200000, 'Open fire in the starfield and shoot down whatever comes at you.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('drop', 'Drop', 'Drop', 'drop xialuo jiangluo tiaoyue impactjs phoboslab dominic szablewski', 'Dominic Szablewski (Phoboslab)', '', '', NULL, '', 0, 2010, 'action', '["动作","街机"]', 75, 0.16, 'io', 'https://impactjs.com/drop/', 0, 0, 0, 1, 0, 0, 1, 'short', 'hosted', '控制下落的小人，踩着方块往下跳', '一款倒置的跳跃游戏：左右移动，落在方块上继续往下，掉出屏幕就结束。也能在手机上玩。', 'An upside-down jumping game: move left and right, land on blocks as you fall, and try not to drop off the screen. It also works on a phone.', '由 Dominic Szablewski（Phoboslab）制作，2010 年起在 impactjs.com/drop 公开发布。原页托管在 impactjs.com/drop，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Dominic Szablewski (Phoboslab) and published at impactjs.com/drop since 2010. Hosted at impactjs.com/drop; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/drop.jpg', 1280, 800, 'center', '["assets/posters/drop.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -46, 1795399200000, 'Steer the falling figure and keep landing on the blocks below.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('shark-game', 'Shark Game', 'Shark Game', 'shark game shayu youxi shayuyouxi incremental idle cirrial cirri', 'Cirrial', '', '', NULL, '', 0, 2014, 'idle', '["放置","模拟"]', 215, 0.12, 'clicker', 'https://cirri.al/sharks/', 0, 0, 0, 1, 0, 0, 1, 'mid', 'hosted', '你是一条鲨鱼，在陌生的海里慢慢变强', '一款放置增量游戏：点「抓鱼」吃掉鲱鱼，再把资源花在进化、雇佣和探索上，一点点揭开这片海的秘密。', 'An incremental idle game: click Catch fish to eat a herring, then spend resources on evolution, helpers and exploration as the sea slowly opens up.', '由 Cirrial 制作，2014 年起在 cirri.al/sharks 公开发布，源码以 MIT 许可在 GitHub 发布。原页托管在 cirri.al/sharks，不是即玩的作品。在即玩里直接打开原作。存档保存在浏览器本地，开玩不用登录。', 'Made by Cirrial and published at cirri.al/sharks since 2014; the source is MIT-licensed on GitHub. Hosted at cirri.al/sharks; it is not a Jiwan original. It opens here. Saves stay in your browser; no account needed.', 'assets/posters/shark-game.jpg', 1280, 800, 'center', '["assets/posters/shark-game.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -45, 1795399200000, 'You are a shark in a strange sea, growing stronger little by little.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('clickpocalypse-2', 'Clickpocalypse 2', 'CLICKPOCALYPSE II', 'clickpocalypse 2 dianji mori idle rpg fangzhi maoxianzhe minmaxia jim hayes jim808', 'Jim K. Hayes (Minmaxia)', '', '', NULL, '', 0, 2015, 'idle', '["放置","角色扮演"]', 30, 0.08, 'clicker', 'https://minmaxia.com/c2/', 0, 0, 0, 1, 0, 0, 1, 'mid', 'hosted', '组好四人小队，把地牢里的怪物点掉', '一款放置式小队 RPG：选好最多四名冒险者，看他们自动探索地牢、打怪和拾取装备，再把点数花在成长上。', 'An idle party RPG: pick up to four adventurers, watch them explore dungeons, fight and loot on their own, and spend points to grow stronger.', '由 Jim K. Hayes（Minmaxia）制作，2015 年起在 minmaxia.com/c2 公开发布。原页托管在 minmaxia.com/c2，不是即玩的作品。在即玩里直接打开原作。存档保存在浏览器本地，开玩不用登录。', 'Made by Jim K. Hayes (Minmaxia) and published at minmaxia.com/c2 since 2015. Hosted at minmaxia.com/c2; it is not a Jiwan original. It opens here. Saves stay in your browser; no account needed.', 'assets/posters/clickpocalypse-2.jpg', 1280, 800, 'center', '["assets/posters/clickpocalypse-2.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -44, 1795399200000, 'Assemble a party of four and click through the dungeon''s monsters.', '', '', 1);
